"""Broadcast message bus distributing cache invalidations."""

from typing import List
from message import InvalidationMessage


class InvalidationBus:
    def __init__(self):
        self.listeners = []

    def register_node(self, node) -> None:
        self.listeners.append(node)

    def broadcast(self, msg: InvalidationMessage) -> None:
        for node in self.listeners:
            if node.node_id != msg.sender_id:
                node.on_invalidation(msg)

