from typing import Any, Dict, Optional
from invalidation_bus import InvalidationBus
from message import InvalidationMessage


class CacheNode:
    def __init__(self, node_id: str, bus: InvalidationBus):
        self.node_id = node_id
        self.bus = bus
        self.store: Dict[str, Any] = {}
        self.versions: Dict[str, int] = {}
        bus.register_node(self)

    def put(self, key: str, val: Any, version: int) -> None:
        self.store[key] = val
        self.versions[key] = version
        self.bus.broadcast(InvalidationMessage(self.node_id, key, version))

    def get(self, key: str) -> Optional[Any]:
        return self.store.get(key)

    def on_invalidation(self, msg: InvalidationMessage) -> None:
        curr_ver = self.versions.get(msg.key, 0)
        # Only invalidate if remote message has higher or equal version
        if msg.version >= curr_ver:
            self.store.pop(msg.key, None)
            self.versions[msg.key] = msg.version
